/**
 * NavGrid — the walkable space of the house as a grid, and A* over it.
 *
 * §16 of the spec asks for "NavMesh or equivalent walkable navigation graph". This is the equivalent,
 * and the equivalence is not a compromise — it is the better fit for *this* house. Every room in
 * HouseRooms is an axis-aligned rectangle, every wall is an axis-aligned box, and `buildHouse()`
 * already produces the AABB list the player's own collision uses. A uniform grid rasterised from
 * exactly those two inputs is therefore guaranteed to agree with where the player can walk, which an
 * autogenerated navmesh is not: a navmesh triangulated from wall geometry can and does disagree with
 * a box-based capsule at every doorway, and the failure mode is Daayan wedging herself in a jamb.
 *
 * Two things make the grid trustworthy rather than merely cheap:
 *
 * 1. **It is inflated.** A cell is walkable only if a disc of `agentRadius` centred on it clears every
 *    AABB. That is what stops her cutting a corner closely enough to clip a wall, and it means the
 *    path A* returns is already legal for a body of her width.
 * 2. **It is stair-aware.** The house has three walkable levels (cellar stair down to y -3, ground at
 *    0, upper stair up to y 2.4) and `houseFloors()` already describes every one of them as a rect at
 *    a known height. Cells carry the floor height they sit on, so "can I step from A to B" is a
 *    height-delta test rather than a special case, and movement between storeys falls out of the same
 *    flood fill that handles the rest of the house.
 *
 * Cost: at 0.25 m the house is roughly 190 x 115 cells, a one-off bake of a few tens of thousands of
 * AABB tests. A* over that is sub-millisecond, and it is throttled to ≤6 Hz anyway (§11).
 */

import type { AABB } from '@/player/FPController';
import type { FloorRect } from '@/world/HouseLayout';

/** Cell size in metres. 0.25 keeps a 0.7 m doorway 2 cells wide even after inflation. */
export const CELL = 0.25;

/**
 * How wide a body the grid must admit. Daayan's model is fitted to 1.85 m tall and her shoulders
 * measure about 0.45 m, so 0.30 of radius is generous rather than tight — deliberately, because a
 * grid that only just admits her is a grid that produces paths she then gets stuck on.
 */
export const AGENT_RADIUS = 0.3;

/**
 * Largest floor-height step that may be walked. Below the player controller's own step-up, so
 * anything she can traverse the player can too, and she can never reach a ledge the player cannot.
 */
export const MAX_STEP = 0.42;

/**
 * How far a caller's requested height may be off before `nearestWalkable` refuses a cell, in metres.
 *
 * **This is a tolerance on a caller's *hint*, not a storey constraint** — and conflating the two is a
 * mistake worth recording, because tightening it looks like the fix for a storey-confusion bug and is
 * not.
 *
 * It has to admit two different height conventions, both of which reach this function:
 *
 *   - the AI passes **floor** heights, from `NavPoint.y` and `houseFloors()`;
 *   - scene code passes **eye** heights. `SPAWN.y` is 2.17 and is the player's *eye* on the ground
 *     floor (`HouseScene` warps the controller there, and re-warps to `mattressY + 1.7`), not a floor.
 *
 * An eye height is ~1.7 m above its floor, so any value below that rejects every eye-height caller —
 * which is exactly what a trial at 1.2 m and 1.5 m did to `SPAWN`, `recovery-check` and the patrol
 * suite. 3.0 m is kept because it is comfortably above an eye height with margin, and because the
 * property this function actually needs is *"find the nearest walkable cell to this hint"*, which is
 * a proximity question and not a floor question.
 *
 * The storey bug that made her never patrol upstairs was **not** here. It was in `findPath`, which
 * identified its goal by XZ alone and then overwrote the final node's height with the requested one —
 * so a first-floor destination at an XZ shared with a stair column was "reached" at the stair tread.
 * See the goal-height check in `findPath`. Fixing that does not require touching this constant, and
 * the two must not be confused again: this one is about *finding a cell*, that one is about *proving
 * you arrived at the right one*.
 */
export const STOREY_TOLERANCE = 3.0;

/** Traversal cost multipliers (§17). Open corridor and normal room share the baseline. */
export const COST_ROOM = 1.0;
export const COST_CORRIDOR = 0.85;
export const COST_STAIR = 1.35;

/**
 * The cheapest terrain multiplier any cell can carry, which is what the A* heuristic must be scaled by.
 *
 * Scaling the heuristic by COST_ROOM instead looks equivalent and is not: a step's real cost is
 * `step * terrain` and corridor terrain is 0.85, so a heuristic at 1.0 *overestimates* the remaining
 * distance in exactly the corridors the long routes run through. An overestimating heuristic is no
 * longer admissible, A* stops being optimal and starts behaving like Dijkstra, and the node budget is
 * spent before a cross-house route is settled — which is precisely how "kitchen to the upper flat"
 * came out as no-path while a BFS from the same cell reached it easily.
 *
 * At MIN_TERRAIN_COST the estimate can never exceed the true remaining cost, so the search stays
 * directed. Kept as a derived constant rather than a literal so that lowering COST_CORRIDOR below it
 * cannot silently reintroduce the bug.
 */
export const MIN_TERRAIN_COST = Math.min(COST_ROOM, COST_CORRIDOR);
/** Narrow passages are not modelled as separate cells; the inflation already encodes them. */

/** Bitmask directions for the A* neighbour test, 4- and 8-connected kept apart for the corner rule. */
const ORTHO: readonly (readonly [number, number])[] = [
  [1, 0],
  [-1, 0],
  [0, 1],
  [0, -1],
];
const DIAG: readonly (readonly [number, number])[] = [
  [1, 1],
  [1, -1],
  [-1, 1],
  [-1, -1],
];

export interface NavPoint {
  x: number;
  y: number;
  z: number;
}

/**
 * A baked navigation grid.
 *
 * The grid is indexed [ix][iz] with ix = floor((x - minX) / CELL). Kept as a flat Float32Array pair
 * rather than an object array: 20 k cells of small objects is a lot of garbage for no benefit, and
 * the queries are all numeric anyway.
 */
export class NavGrid {
  readonly minX: number;
  readonly minZ: number;
  readonly cols: number;
  readonly rows: number;
  readonly cell = CELL;
  /** NaN means unwalkable. Otherwise the floor height in world units. */
  private readonly height: Float32Array;
  /** Cost multiplier per cell; only meaningful where `height` is finite. */
  private readonly costMult: Float32Array;
  /** Live cost field, written during a search. Not part of the baked data. */
  private readonly gScore: Float32Array;
  private readonly fScore: Float32Array;
  private readonly cameFrom: Int32Array;
  private readonly stamp: Int32Array;
  /** Search id at which a node was settled. Distinguishes "closed" from "seen" in A*. */
  private readonly closed: Int32Array;
  private searchId = 0;

  constructor(minX: number, minZ: number, cols: number, rows: number) {
    this.minX = minX;
    this.minZ = minZ;
    this.cols = cols;
    this.rows = rows;
    const n = cols * rows;
    this.height = new Float32Array(n).fill(NaN);
    this.costMult = new Float32Array(n).fill(1);
    this.gScore = new Float32Array(n);
    this.fScore = new Float32Array(n);
    this.cameFrom = new Int32Array(n);
    this.stamp = new Int32Array(n);
    this.closed = new Int32Array(n);
  }

  private index(ix: number, iz: number): number {
    return iz * this.cols + ix;
  }

  inBounds(ix: number, iz: number): boolean {
    return ix >= 0 && iz >= 0 && ix < this.cols && iz < this.rows;
  }

  cellX(ix: number): number {
    return this.minX + (ix + 0.5) * CELL;
  }

  cellZ(iz: number): number {
    return this.minZ + (iz + 0.5) * CELL;
  }

  ixAt(x: number): number {
    return Math.floor((x - this.minX) / CELL);
  }

  izAt(z: number): number {
    return Math.floor((z - this.minZ) / CELL);
  }

  /** True when the cell holds walkable floor. */
  walkable(ix: number, iz: number): boolean {
    if (!this.inBounds(ix, iz)) return false;
    return Number.isFinite(this.height[this.index(ix, iz)] as number);
  }

  /** Floor height, or NaN when unwalkable. */
  heightAt(ix: number, iz: number): number {
    if (!this.inBounds(ix, iz)) return NaN;
    return this.height[this.index(ix, iz)] as number;
  }

  /** Floor height at a world XZ, or NaN. Convenience for callers holding positions. */
  heightAtWorld(x: number, z: number): number {
    return this.heightAt(this.ixAt(x), this.izAt(z));
  }

  private set(ix: number, iz: number, y: number, cost: number): void {
    if (!this.inBounds(ix, iz)) return;
    const i = this.index(ix, iz);
    const cur = this.height[i] as number;
    // Higher surface wins. This is the opposite of the obvious "keep the lowest floor" rule, and the
    // reason is stairs: `houseFloors()` describes the cellar stair as a landing rect at y = 0 that
    // covers the *whole* shaft, plus fifteen treads at descending heights inside it. Keeping the lower
    // value lets that landing overwrite all fifteen treads, the staircase flattens to y = 0, and the
    // cellar becomes unreachable through the floor it is actually reached through.
    //
    // A tread occluding the landing beneath it is also what is physically true: you stand on the
    // tread, not on the slab under it.
    if (Number.isFinite(cur) && cur >= y) return;
    this.height[i] = y;
    this.costMult[i] = cost;
  }

  // --- Baking -------------------------------------------------------------

  /**
   * Rasterise the floor rects, then carve out anything a body of `AGENT_RADIUS` cannot pass.
   *
   * `floors` is `houseFloors()` — every walkable rectangle in the house, stairs included. `obstacles`
   * is the build's AABB list, which already contains every wall segment, and to which the caller adds
   * prop and furniture boxes so she paths around the sofa rather than through it.
   */
  static bake(floors: readonly FloorRect[], obstacles: readonly AABB[]): NavGrid {
    let minX = Infinity;
    let maxX = -Infinity;
    let minZ = Infinity;
    let maxZ = -Infinity;
    for (const f of floors) {
      if (f.x0 < minX) minX = f.x0;
      if (f.x1 > maxX) maxX = f.x1;
      if (f.z0 < minZ) minZ = f.z0;
      if (f.z1 > maxZ) maxZ = f.z1;
    }
    // A one-cell margin so a point exactly on a rect edge still lands inside the array.
    minX -= CELL;
    minZ -= CELL;
    maxX += CELL;
    maxZ += CELL;
    const cols = Math.ceil((maxX - minX) / CELL);
    const rows = Math.ceil((maxZ - minZ) / CELL);
    const grid = new NavGrid(minX, minZ, cols, rows);

    // 1. Floors. Order does not matter — `set` resolves overlaps by keeping the higher surface, so a
    //    stair tread beats the landing slab beneath it regardless of which rect is painted first.
    for (const f of floors) {
      const ix0 = Math.max(0, grid.ixAt(f.x0));
      const ix1 = Math.min(cols - 1, grid.ixAt(f.x1 - 1e-6));
      const iz0 = Math.max(0, grid.izAt(f.z0));
      const iz1 = Math.min(rows - 1, grid.izAt(f.z1 - 1e-6));
      // Rect areas are large enough to be worth classifying for §17's cost field.
      const w = f.x1 - f.x0;
      const d = f.z1 - f.z0;
      const cost = w < 3.6 || d < 3.6 ? COST_CORRIDOR : COST_ROOM;
      for (let iz = iz0; iz <= iz1; iz++) {
        for (let ix = ix0; ix <= ix1; ix++) grid.set(ix, iz, f.y, cost);
      }
    }

    // 2. Inflation. Clear every cell whose disc overlaps an obstacle, and every cell whose floor is
    //    not flat enough across the disc to stand on. Done after the full rasterise so an obstacle
    //    near a floor's edge is handled once rather than per rect.
    //
    //    Cells are tested against obstacles by disc-overlap, which for an axis-aligned box is a
    //    clamped closest-point distance — exact, and far cheaper than sampling the disc.
    const rSq = AGENT_RADIUS * AGENT_RADIUS;
    for (const ob of obstacles) {
      // Obstacles entirely below the walkable band or entirely above head height do not obstruct.
      // 0.05 is the tolerance for a floor slab sitting exactly at its own cell's height.
      const ix0 = Math.max(0, grid.ixAt(ob.minX - AGENT_RADIUS));
      const ix1 = Math.min(cols - 1, grid.ixAt(ob.maxX + AGENT_RADIUS));
      const iz0 = Math.max(0, grid.izAt(ob.minZ - AGENT_RADIUS));
      const iz1 = Math.min(rows - 1, grid.izAt(ob.maxZ + AGENT_RADIUS));
      for (let iz = iz0; iz <= iz1; iz++) {
        for (let ix = ix0; ix <= ix1; ix++) {
          const i = grid.index(ix, iz);
          const y = grid.height[i] as number;
          if (!Number.isFinite(y)) continue;
          // Vertical overlap test against the cell's own floor, 1.9 m of headroom.
          if (ob.maxY <= y + 0.05) continue;
          if (ob.minY >= y + 1.9) continue;
          const cx = grid.cellX(ix);
          const cz = grid.cellZ(iz);
          const dx = Math.max(ob.minX - cx, 0, cx - ob.maxX);
          const dz = Math.max(ob.minZ - cz, 0, cz - ob.maxZ);
          if (dx * dx + dz * dz < rSq) grid.height[i] = NaN;
        }
      }
    }

    // 3. Third pass: reject cells the agent cannot actually stand on because the ground beneath them
    //    drops away within a stride.
    //
    //    This is the one test that has to distinguish a staircase from a cliff, and the first version
    //    of it got that wrong in a way worth recording, because the mistake is the natural one: it
    //    rejected any cell whose disc of influence contained a neighbour more than MAX_STEP away in
    //    height. On a real staircase every tread is ~0.3 m from the next and the treads are ~0.47 m
    //    deep, so *every tread cell* sees a 0.3 m neighbour inside a 0.3 m radius and the entire
    //    staircase is deleted. The cellar and the upper flat then have no route to them at all, which
    //    is exactly the unreachable-storey failure the bake test caught.
    //
    //    The distinction is gradient, not delta. A stair rises at most MAX_STEP over the ~0.47 m of
    //    one tread — a slope of about 0.9 — while a landing's edge drops 2.4 m over the same distance.
    //    So the test is: for every neighbour inside the body radius, the rise must be proportionate to
    //    the horizontal distance it occurs over. A cell is a cliff only when the ground is missing, or
    //    falls further than a stride would carry it, at a gradient no stair in this house has.
    const stepDisc = Math.ceil(AGENT_RADIUS / CELL);
    for (let iz = 0; iz < rows; iz++) {
      for (let ix = 0; ix < cols; ix++) {
        const i = grid.index(ix, iz);
        const y = grid.height[i] as number;
        if (!Number.isFinite(y)) continue;
        let cliff = false;
        for (let dz = -stepDisc; dz <= stepDisc && !cliff; dz++) {
          for (let dx = -stepDisc; dx <= stepDisc; dx++) {
            const d2 = dx * dx + dz * dz;
            if (d2 > stepDisc * stepDisc) continue;
            if (d2 === 0) continue;
            const nx = ix + dx;
            const nz = iz + dz;
            // A walkable neighbour governs by the same gradient rule.
            if (grid.walkable(nx, nz)) {
              const ny = grid.heightAt(nx, nz);
              const dist = Math.sqrt(d2) * CELL;
              // Allow MAX_STEP of rise per cell of distance, with a floor of one cell so a
              // single-cell neighbour is judged by the step rule rather than by its own distance.
              const allowed = MAX_STEP * Math.max(1, dist / CELL);
              if (Math.abs(ny - y) > allowed + 0.01) {
                cliff = true;
                break;
              }
              continue;
            }
            // An out-of-grid neighbour is the edge of the world, which is a cliff by definition.
            if (!grid.inBounds(nx, nz)) {
              cliff = true;
              break;
            }
          }
        }
        if (cliff) grid.height[i] = NaN;
      }
    }

    grid.pruneIslands();
    return grid;
  }

  /**
   * Drop walkable cells that cannot reach the bulk of the house.
   *
   * The inflation pass can leave sealed pockets — most of them genuine (inside a wall's footprint, in
   * the closed coffin room) but some are artefacts of the disc test at the corners of an L-shaped
   * room. §16: "Get stuck on corners" / "Constantly oscillate between two positions" are exactly the
   * symptoms of a path into a pocket it cannot get out of, so removing them is worth doing.
   *
   * The version of this that kept only the *largest* component was wrong, and its failure mode is
   * worth recording because it is silent and total: the upper flat is reached only by a staircase, and
   * any error in the stair modelling — which there was — disconnects it, whereupon "keep the largest"
   * deletes an entire storey of the house from the navigation graph without a word. The AI then
   * patrols one floor forever and nothing anywhere reports a problem.
   *
   * So the rule is "keep every component above a floor", not "keep the biggest": a storey is ~1500
   * cells, a corner artefact is a handful. Anything dropped is counted in `droppedCells` so a baker
   * can assert it is small.
   */
  private pruneIslands(): void {
    const n = this.cols * this.rows;
    const comp = new Int32Array(n).fill(-1);
    const sizes: number[] = [];
    const stack: number[] = [];
    /** Components smaller than this are treated as artefacts and removed. */
    const MIN_COMPONENT = 40;

    for (let start = 0; start < n; start++) {
      if (comp[start] !== -1) continue;
      if (!Number.isFinite(this.height[start] as number)) {
        comp[start] = -2;
        continue;
      }
      const id = sizes.length;
      let size = 0;
      stack.length = 0;
      stack.push(start);
      comp[start] = id;
      while (stack.length > 0) {
        const cur = stack.pop() as number;
        size++;
        const cx = cur % this.cols;
        const cz = (cur - cx) / this.cols;
        const cy = this.height[cur] as number;
        for (let k = 0; k < 8; k++) {
          const [dx, dy] =
            k < 4 ? (ORTHO[k] as readonly [number, number]) : (DIAG[k - 4] as readonly [number, number]);
          const nx = cx + dx;
          const ny = cz + dy;
          if (!this.inBounds(nx, ny)) continue;
          const ni = this.index(nx, ny);
          if (comp[ni] !== -1) continue;
          const nHeight = this.height[ni] as number;
          if (!Number.isFinite(nHeight)) {
            comp[ni] = -2;
            continue;
          }
          if (Math.abs(nHeight - cy) > MAX_STEP) continue;
          if (dx !== 0 && dy !== 0) {
            if (!this.walkable(cx + dx, cz) || !this.walkable(cx, cz + dy)) continue;
          }
          comp[ni] = id;
          stack.push(ni);
        }
      }
      sizes[id] = size;
    }

    let dropped = 0;
    for (let i = 0; i < n; i++) {
      const c = comp[i] as number;
      if (c < 0) continue;
      if ((sizes[c] as number) < MIN_COMPONENT) {
        this.height[i] = NaN;
        dropped++;
      }
    }
    this.droppedCells = dropped;
  }

  /** Cells removed by the island prune, for the bake diagnostics. */
  droppedCells = 0;

  // --- Queries ------------------------------------------------------------

  /**
   * Nearest walkable cell to a world position, searched outward in rings.
   *
   * Searched rather than rounded because the single nearest cell can be a wall: a waypoint authored
   * half a metre inside a doorway's jamb, or a sound's estimated position that lands in a wall, both
   * need to resolve to the closest place she can actually stand. `maxRadius` bounds the spiral so a
   * position in solid rock returns null instead of scanning the whole grid.
   *
   * `nearY`, when given, is a **storey preference, not a filter** — the caller knows which floor they
   * mean (a waypoint's own height, a chase target's storey, a sound's storey), but scene code passes
   * *eye* heights (~1.6 m above the floor), so the hard filter stays the generous `STOREY_TOLERANCE`
   * window and the storey is chosen by the squared height term in the score. The exact-cell fast
   * path is the one exception: it only fires when the query's own cell is within `MAX_STEP` of the
   * hint, i.e. unambiguously the caller's storey. An eye-height hint over a mid-flight tread must
   * fall through to the scored search, or "she climbed three steps and stopped" returns.
   *
   * The search scores **globally across rings**, never returning the first non-empty ring. That
   * early return was the residual form of the CHASE-to-upstairs stall: the per-ring best only
   * compares cells at one radius, so a tread at y = 1.2 in ring 4 beat the real upper floor at
   * y = 2.4 in ring 12 without the two ever being compared, and she stopped mid-flight at y = 0.90
   * forever. Scored globally, the tread's height error (4 · 2.82² ≈ 32) loses to the floor's plan
   * distance (≈ 8 + 4 · 1.62² ≈ 19), which is what the height term was always for. The loop still
   * terminates early — once a ring's closest possible plan distance exceeds the best score found, no
   * later ring can win — so a same-storey query still costs a ring or three.
   *
   * When `nearY` is **omitted** the caller has no storey in mind (the patrol waypoint bake passes
   * none), the score is plain plan distance, and the result is simply the nearest walkable cell.
   */
  nearestWalkable(x: number, z: number, maxRadius = 12, nearY?: number): NavPoint | null {
    // The tolerance must admit an eye-height caller (an eye is ~1.6 m above its floor, and scene code
    // like `SPAWN` passes those), so it cannot be tighter than that. 3.0 m is the smallest window
    // that does, with margin. It deliberately cannot resolve *which* storey — that is what the
    // squared height term in the scoring loop is for — it only filters out cells that are plainly
    // off the map entirely.
    const yTol = STOREY_TOLERANCE;
    const ix0 = this.ixAt(x);
    const iz0 = this.izAt(z);
    if (this.walkable(ix0, iz0)) {
      const y = this.heightAt(ix0, iz0);
      // Unambiguous only at MAX_STEP: a looser test here short-circuits the scored search below for
      // exactly the eye-height-over-a-staircase queries that search exists to get right.
      if (nearY === undefined || Math.abs(y - nearY) <= MAX_STEP) return { x, y, z };
    }
    const maxRing = Math.ceil(maxRadius / CELL);
    let bestPoint: NavPoint | null = null;
    let bestScore = Infinity;
    for (let r = 1; r <= maxRing; r++) {
      // A ring's cells are all at least (r-1)*CELL away in plan (the query sits somewhere inside
      // ring 0's cell), and a score is at least its plan distance — so once that floor beats the
      // best score, every remaining ring can only do worse. Conservative by a full cell, which
      // costs an extra ring or two of scanning and buys not having to think about cell centres.
      if (bestPoint) {
        const floorDist = (r - 1) * CELL;
        if (floorDist * floorDist > bestScore) break;
      }
      // Perimeter walk of the ring; a full square scan would be O(r²) for no gain.
      for (let dx = -r; dx <= r; dx++) {
        for (let dz = -r; dz <= r; dz++) {
          if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
          const ix = ix0 + dx;
          const iz = iz0 + dz;
          if (!this.walkable(ix, iz)) continue;
          const y = this.heightAt(ix, iz);
          if (nearY !== undefined && Math.abs(y - nearY) > yTol) continue;
          const px = this.cellX(ix);
          const pz = this.cellZ(iz);
          const d = (px - x) * (px - x) + (pz - z) * (pz - z);
          // Prefer the closest, but among near-equals prefer the one at the caller's own height.
          //
          // The height term is *squared* and heavy, and the reason matters more than the tuning. The
          // old linear 0.25 weight let a cell 3.1 m away in Y beat a cell at the right height 2.5 m
          // away in X, because 3.1 * 0.25 = 0.775 loses to a few metres of squared horizontal distance.
          // Concretely: a CHASE to a player standing at the top of the up-shaft (y = 4.0 eye height)
          // resolved to the shaft tread at y = 0.9 — 3.1 m straight down — because it sat 0.5 m closer
          // on the floor plan. She would climb the three treads to that cell, reach the one-node
          // "path", stop, and the stuck recovery would repath her to the same cell forever. Squaring
          // the height error (3.1² = 9.6) makes the wrong storey strictly worse than the right one,
          // which is the whole point of the caller passing a height at all.
          const score = nearY === undefined ? d : d + Math.abs(y - nearY) * Math.abs(y - nearY) * 4;
          if (score < bestScore) {
            bestScore = score;
            bestPoint = { x: px, y, z: pz };
          }
        }
      }
    }
    return bestPoint;
  }

  /** Walkable neighbours of a cell, honouring the height rule and the no-corner-cutting rule. */
  private neighbours(ix: number, iz: number, out: number[]): void {
    out.length = 0;
    const y = this.heightAt(ix, iz);
    if (!Number.isFinite(y)) return;
    for (let k = 0; k < 8; k++) {
      const [dx, dz] = k < 4 ? (ORTHO[k] as readonly [number, number]) : (DIAG[k - 4] as readonly [number, number]);
      const nx = ix + dx;
      const nz = iz + dz;
      if (!this.walkable(nx, nz)) continue;
      const ny = this.heightAt(nx, nz);
      if (Math.abs(ny - y) > MAX_STEP) continue;
      if (dx !== 0 && dz !== 0 && (!this.walkable(ix + dx, iz) || !this.walkable(ix, iz + dz))) continue;
      out.push(this.index(nx, nz));
    }
  }

  /** Octile distance heuristic, admissible for the 8-connected cost below. */
  private heuristic(ax: number, az: number, bx: number, bz: number): number {
    const dx = Math.abs(ax - bx);
    const dz = Math.abs(az - bz);
    const dmin = Math.min(dx, dz);
    const dmax = Math.max(dx, dz);
    return dmax + (Math.SQRT2 - 1) * dmin;
  }

  /**
   * A* between two world points. Returns a list of world positions *excluding* the start and
   * including the goal, or null when no route exists.
   *
   * Straight-line smoothing is applied to the result: A* on an 8-grid produces staircases, and a body
   * walking a staircase of 0.25 m steps reads as a robot. The smoother pulls out any vertex the
   * segment between its neighbours can replace, which turns a 40-leg staircase into the 4 or 5 corners
   * a person would actually walk.
   */
  findPath(from: NavPoint, to: NavPoint, maxNodes = 0): NavPoint[] | null {
    const s = this.nearestWalkable(from.x, from.z, 4, from.y);
    const g = this.nearestWalkable(to.x, to.z, 10, to.y);
    if (!s || !g) return null;

    // Default budget: the whole grid. A search that has settled every walkable cell and still not
    // reached the goal has genuinely proven there is no route, so capping below that can only turn a
    // real path into a false negative — which is exactly what a fixed 20 k did to the longest route
    // in the house. The cap exists to bound a pathological search, not to bound a normal one, so it
    // is set well above any real path's expansion count.
    const budget = maxNodes > 0 ? maxNodes : this.cols * this.rows + 1;

    const six = this.ixAt(s.x);
    const siz = this.izAt(s.z);
    const gix = this.ixAt(g.x);
    const giz = this.izAt(g.z);

    const start = this.index(six, siz);
    const goal = this.index(gix, giz);
    if (start === goal) return [{ x: g.x, y: g.y, z: g.z }];

    this.searchId++;
    const id = this.searchId;
    const open = new MinHeap();
    this.stamp[start] = id;
    this.gScore[start] = 0;
    this.fScore[start] = this.heuristic(six, siz, gix, giz);
    this.cameFrom[start] = -1;
    open.push(start, this.fScore[start] as number);
    const nbrs: number[] = [];
    let expanded = 0;

    while (open.size > 0) {
      const cur = open.pop() as number;
      // Lazy deletion: a cell can be pushed more than once as its g-score improves, so discard the
      // stale copies here rather than paying for a decrease-key.
      if (this.closed[cur] === id) continue;
      this.closed[cur] = id;
      if (cur === goal) return this.reconstruct(cur, g);
      if (++expanded > budget) break;

      const cx = cur % this.cols;
      const cz = (cur - cx) / this.cols;
      this.neighbours(cx, cz, nbrs);
      for (const ni of nbrs) {
        // A closed node is final. Without this the search re-expands everything it has already
        // settled, the open set balloons, and the node budget is spent before the goal is reached —
        // which is exactly how the longest route in the house (kitchen to the upper flat) reported
        // "no path" while every one of its legs pathfound fine.
        if (this.closed[ni] === id) continue;
        const nx = ni % this.cols;
        const nz = (ni - nx) / this.cols;
        const diag = nx !== cx && nz !== cz;
        const step = diag ? Math.SQRT2 : 1;
        const curY = this.heightAt(cx, cz);
        const nextY = this.heightAt(nx, nz);
        // §17: stairs cost more, and a rise costs a little more than a flat step of the same length.
        const rise = Math.abs(nextY - curY);
        const terrain = (this.costMult[ni] as number) + rise * COST_STAIR;
        const tentative = (this.gScore[cur] as number) + step * terrain;
        if (this.stamp[ni] === id && tentative >= (this.gScore[ni] as number)) continue;
        this.stamp[ni] = id;
        this.cameFrom[ni] = cur;
        this.gScore[ni] = tentative;
        this.fScore[ni] = tentative + this.heuristic(nx, nz, gix, giz) * MIN_TERRAIN_COST;
        open.push(ni, this.fScore[ni] as number);
      }
    }
    return null;
  }

  private reconstruct(goalCell: number, goal: NavPoint): NavPoint[] {
    const cells: number[] = [];
    let cur = goalCell;
    let guard = 0;
    while (cur !== -1 && guard++ < 100000) {
      cells.push(cur);
      cur = this.cameFrom[cur] as number;
    }
    cells.reverse();
    const pts: NavPoint[] = cells.map((i) => {
      const ix = i % this.cols;
      const iz = (i - ix) / this.cols;
      return { x: this.cellX(ix), y: this.heightAt(ix, iz), z: this.cellZ(iz) };
    });
    // Replace the last cell with the caller's exact XZ goal so she arrives where asked, not one cell
    // short of it — but keep the *resolved* height, not the caller's. The caller may pass an eye
    // height (a chase to the player) and the walkable surface `nearestWalkable` found for it is what
    // she can actually stand on. Overwriting with the caller's y once made a path to the up-shaft
    // claim it ended at y = 4.0 while physically ending at y = 0.9, and she stopped on the tread.
    if (pts.length > 0) pts[pts.length - 1] = { x: goal.x, y: pts[pts.length - 1]!.y, z: goal.z };
    return this.simplify(pts);
  }

  /**
   * Pull a staircase of grid steps back to the corners a person would walk.
   *
   * Greedy: from each kept vertex, extend as far as the segment stays clear, keep that endpoint. This
   * is O(n²) in path length, which is fine — paths here are tens of cells, not thousands.
   *
   * A method rather than a free function because the clearance test has to ask the grid about
   * terrain, and terrain is what `segmentClear` already knows how to sample.
   */
  private simplify(pts: NavPoint[]): NavPoint[] {
    if (pts.length <= 2) return pts;
    const out: NavPoint[] = [pts[0] as NavPoint];
    let i = 0;
    while (i < pts.length - 1) {
      let best = i + 1;
      // Search from the far end so we keep the longest legal run available.
      for (let j = pts.length - 1; j > i + 1; j--) {
        if (this.segmentClear(pts[i] as NavPoint, pts[j] as NavPoint, MAX_STEP * 1.6)) {
          best = j;
          break;
        }
      }
      out.push(pts[best] as NavPoint);
      i = best;
    }
    return out;
  }

  /**
   * True when a straight walk between two points does not cross blocked space.
   *
   * Two separate conditions, and both are needed:
   *
   *   1. **Every sampled cell is walkable** and no *consecutive* pair rises more than `maxStep`.
   *   2. **The whole segment's total height change is within `maxStep`.**
   *
   * The second condition is the one that was missing, and its absence broke every staircase in the
   * house. `Locomotion` steers toward a path node and moves in **plan view** — it integrates x/z and
   * takes y from the nav grid. So a segment is only walkable if it is walkable *as a straight line on
   * the floor plan*. Condition 1 alone cannot see that: across the up-shaft's 8 treads, consecutive
   * samples 0.30 m apart in height are each under the 0.672 m per-sample limit, so a 3.25 m segment
   * climbing from y = 0.90 to y = 2.40 was reported clear. She would then walk horizontally into the
   * shaft wall and wedge at y = 0.90 forever — which is exactly the stall that survived every other
   * fix, and the reason she never patrolled upstairs.
   *
   * Comparing the segment's *ends* closes it: a stair's endpoints always differ by the full climb, so
   * a hop from the middle of a flight to the top is rejected and the smoother is forced to keep the
   * intermediate treads as real waypoints. Short flat segments and gentle ramps are unaffected.
   */
  segmentClear(a: NavPoint, b: NavPoint, maxStep = MAX_STEP): boolean {
    const dx = b.x - a.x;
    const dz = b.z - a.z;
    const dist = Math.hypot(dx, dz);
    const startY = this.heightAtWorld(a.x, a.z);
    const endY = this.heightAtWorld(b.x, b.z);
    if (!Number.isFinite(startY) || !Number.isFinite(endY)) return false;
    // The whole-segment height change. A body following this line in plan view has to absorb all of
    // it, so it is bounded by the same step limit as any single grid step.
    if (Math.abs(endY - startY) > maxStep) return false;

    const steps = Math.max(1, Math.ceil(dist / (CELL * 0.5)));
    let prevY = startY;
    for (let i = 1; i <= steps; i++) {
      const t = i / steps;
      const x = a.x + dx * t;
      const z = a.z + dz * t;
      const y = this.heightAtWorld(x, z);
      if (!Number.isFinite(y)) return false;
      if (Math.abs(y - prevY) > maxStep) return false;
      prevY = y;
    }
    return true;
  }

  /** Count of walkable cells. Used by the bake diagnostics. */
  walkableCount(): number {
    let n = 0;
    for (let i = 0; i < this.height.length; i++) {
      if (Number.isFinite(this.height[i] as number)) n++;
    }
    return n;
  }
}

/**
 * Binary min-heap over cell indices, keyed by f-score.
 *
 * The first version of A* scanned a plain array for its lowest f, on the reasoning that the open set
 * would never be large enough to care. It is: a 25 k-cell grid with a long route across three floors
 * puts thousands of nodes in the open set, the scan turns the search quadratic, and the node budget
 * runs out before the goal is settled. A heap is thirty lines and removes the whole class of failure.
 *
 * Duplicate entries are allowed rather than decrease-key'd: when the same cell is pushed twice the
 * cheaper copy pops first and the stale one is discarded by the caller's closed-set test. That is the
 * standard lazy-deletion heap and it is simpler than maintaining an index map.
 */
class MinHeap {
  private items: number[] = [];
  private keys: number[] = [];

  get size(): number {
    return this.items.length;
  }

  push(item: number, key: number): void {
    this.items.push(item);
    this.keys.push(key);
    let i = this.items.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if ((this.keys[parent] as number) <= (this.keys[i] as number)) break;
      this.swap(i, parent);
      i = parent;
    }
  }

  pop(): number | undefined {
    const n = this.items.length;
    if (n === 0) return undefined;
    const top = this.items[0] as number;
    const lastItem = this.items.pop() as number;
    const lastKey = this.keys.pop() as number;
    if (n > 1) {
      this.items[0] = lastItem;
      this.keys[0] = lastKey;
      let i = 0;
      const size = this.items.length;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let small = i;
        if (l < size && (this.keys[l] as number) < (this.keys[small] as number)) small = l;
        if (r < size && (this.keys[r] as number) < (this.keys[small] as number)) small = r;
        if (small === i) break;
        this.swap(i, small);
        i = small;
      }
    }
    return top;
  }

  private swap(a: number, b: number): void {
    const ti = this.items[a] as number;
    const tk = this.keys[a] as number;
    this.items[a] = this.items[b] as number;
    this.keys[a] = this.keys[b] as number;
    this.items[b] = ti;
    this.keys[b] = tk;
  }
}
